-- Creates the contract_templates table, seeds the active v2.0 template and records the migration.
-- Run once on production (phpMyAdmin > SQL).
CREATE TABLE IF NOT EXISTS `contract_templates` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `version` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `body` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '0',
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `contract_templates` VALUES (1,'v2.0','<h2>1. PARTIES</h2>\n<p><strong>Prestataire :</strong><br>{{provider_name}}<br>{{provider_address}}<br>{{provider_contact}}</p>\n<p><strong>Client :</strong><br>{{client_name}}<br>{{client_email}}<br>Téléphone : {{client_phone}}<br>{{client_address}}</p>\n\n<h2>2. OBJET ET PORTÉE DU SERVICE</h2>\n<p><strong>{{service_name}}</strong></p>\n{{service_description}}\n<p>Toute prestation non expressément décrite est exclue.</p>\n\n<h2>3. PRIX ET MODALITÉS DE PAIEMENT</h2>\n<p><strong>Prix total (taxes incluses) : {{total_price}} {{currency}}<br>Modalité : Paiement unique intégral</strong><br>Les prix s\'entendent taxes incluses : le montant indiqué est le montant payé.</p>\n\n<h2>4. DÉLAIS D\'EXÉCUTION</h2>\n<p>Le prestataire entreprend l\'exécution dans les meilleurs délais suivant le paiement. Les délais communiqués sont indicatifs ; un retard raisonnable ne constitue pas un motif de résolution. Le client est informé par courriel du démarrage des travaux.</p>\n\n<h2>5. OBLIGATIONS DU CLIENT</h2>\n<ul>\n<li>Fournir des informations exactes et complètes.</li>\n<li>Accorder les accès nécessaires (profil Google Business, site web le cas échéant).</li>\n<li>Collaborer de bonne foi avec le prestataire.</li>\n</ul>\n<p>L\'inexécution de ces obligations suspend les délais du prestataire.</p>\n\n<h2>6. EXÉCUTION IMMÉDIATE ET DROIT DE RÉSOLUTION</h2>\n<p>Le client a expressément demandé que l\'exécution commence sans délai. Conformément aux règles applicables aux contrats à distance, le client peut se rétracter tant que l\'exécution n\'a pas commencé ; il reconnaît qu\'une fois le service entièrement exécuté avec son accord préalable exprès, le droit de rétractation ne peut plus être exercé, sous réserve des dispositions impératives de la Loi sur la protection du consommateur (Québec) ou de la législation impérative applicable au lieu de résidence du client.</p>\n\n<h2>7. ABSENCE DE GARANTIE DE RÉSULTATS</h2>\n<p>Les services portent sur des plateformes exploitées par des tiers (notamment Google). Le prestataire s\'engage à des moyens diligents et professionnels ; il ne garantit aucun positionnement, classement, volume d\'avis ou résultat commercial déterminé, ces éléments relevant d\'algorithmes et de décisions de tiers.</p>\n\n<h2>8. LIMITATION DE RESPONSABILITÉ</h2>\n<p>Dans la mesure permise par la loi, la responsabilité totale du prestataire est limitée aux montants effectivement payés par le client au titre de la commande visée, et les dommages indirects, accessoires ou consécutifs (perte de profits, de clientèle ou de données) sont exclus. La présente clause ne limite pas la responsabilité en cas de faute lourde ou intentionnelle, ni les droits impératifs du consommateur.</p>\n\n<h2>9. FORCE MAJEURE</h2>\n<p>Aucune des parties n\'est responsable d\'un manquement résultant d\'un événement échappant à son contrôle raisonnable, y compris la défaillance, la suspension ou la modification des plateformes tierces. Les obligations affectées sont suspendues pendant la durée de l\'événement.</p>\n\n<h2>10. PROTECTION DES RENSEIGNEMENTS PERSONNELS</h2>\n<p>Le prestataire traite les renseignements personnels conformément à sa politique de confidentialité ({{privacy_url}}) et aux lois applicables, dont la Loi 25 (Québec).</p>\n\n<h2>11. POLITIQUE DE REMBOURSEMENT</h2>\n<p>La politique de remboursement s\'applique à cette commande. Elle est consultable à l\'adresse :<br>{{refund_url}}<br>Version acceptée par le client : version {{policy_version}}</p>\n\n<h2>12. DROIT APPLICABLE ET JURIDICTION</h2>\n<p>Le présent contrat est régi par les lois du Québec et les lois fédérales du Canada applicables. Tout différend relève des tribunaux compétents du district judiciaire de Montréal, sous réserve des dispositions impératives conférant compétence aux tribunaux du lieu de résidence du consommateur.</p>\n\n<h2>13. DISPOSITIONS GÉNÉRALES</h2>\n<ul>\n<li>Divisibilité : si une clause est jugée invalide, les autres clauses demeurent pleinement en vigueur.</li>\n<li>Intégralité de l\'entente : le présent contrat, la politique de remboursement et la confirmation de commande constituent l\'entente complète entre les parties.</li>\n<li>Renonciation : le fait de ne pas exercer un droit ne vaut pas renonciation à ce droit.</li>\n</ul>\n\n<h2>14. SIGNATURE ÉLECTRONIQUE ET PREUVE</h2>\n<p>Le client a manifesté son consentement par un procédé électronique fiable au sens de la Loi concernant le cadre juridique des technologies de l\'information (Québec) et, le cas échéant, du règlement eIDAS (UE).</p>\n<blockquote>« Je, {{client_name}}, commande {{service_name}} au montant de {{total_price_fr}} {{currency}} taxes incluses et j\'accepte la politique de remboursement ainsi que les conditions de service. »</blockquote>\n{{consent_timestamp_line}}\n',1,NULL,'2026-11-18 09:53:03','2026-11-18 12:01:36');


INSERT INTO `migrations` (`migration`, `batch`) SELECT '2026_11_18_000100_create_contract_templates_table', COALESCE(MAX(`batch`), 0) + 1 FROM `migrations`;
